1	package vault
2	
3	import (
4		"encoding/base64"
5		"encoding/json"
6		"fmt"
7		"os"
8		"path/filepath"
9		"strings"
10		"sync"
11		"testing"
12		"time"
13	)
14	
15	// helper: put several named files into a fresh store and return its root.
16	func seedVault(t *testing.T, files map[string]string) (string, *Store) {
17		t.Helper()
18		root := filepath.Join(t.TempDir(), "vault")
19		store := New(root)
20		for name, content := range files {
21			if _, err := store.Put(name, writeFile(t, content)); err != nil {
22				t.Fatal(err)
23			}
24		}
25		return root, store
26	}
27	
28	func mustExport(t *testing.T, root, name, base, out string) ExportResult {
29		t.Helper()
30		res, err := New(root).ExportSnapshot(name, base, out)
31		if err != nil {
32			t.Fatalf("export %s: %v", name, err)
33		}
34		return res
35	}
36	
37	func assertEntriesAfterRestore(t *testing.T, root, snap string, want map[string]string) {
38		t.Helper()
39		store := New(root)
40		if err := store.RestoreSnapshot(snap); err != nil {
41			t.Fatalf("restore %s: %v", snap, err)
42		}
43		entries, err := store.List()
44		if err != nil {
45			t.Fatal(err)
46		}
47		if len(entries) != len(want) {
48			t.Fatalf("restore %s: %d entries, want %d (%+v)", snap, len(entries), len(want), entries)
49		}
50		got := map[string]string{}
51		for _, e := range entries {
52			got[e.Name] = e.Digest
53		}
54		for name, content := range want {
55			d, ok := got[name]
56			if !ok {
57				t.Fatalf("restore %s: missing entry %q", snap, name)
58			}
59			if d != digestOf(content) {
60				t.Fatalf("restore %s: entry %q digest %s, want %s", snap, name, d, digestOf(content))
61			}
62		}
63	}
64	
65	func TestExportImportFullRoundTrip(t *testing.T) {
66		src, _ := seedVault(t, map[string]string{
67			"releases/app.txt": "version one\n",
68			"docs/readme.txt":  "version one\n", // same digest, must be carried once
69			"empty.txt":        "",
70		})
71		if _, err := New(src).CreateSnapshot("snap"); err != nil {
72			t.Fatal(err)
73		}
74		out := filepath.Join(t.TempDir(), "snap.pkg")
75		res := mustExport(t, src, "snap", "", out)
76		if res.Entries != 3 || res.Objects != 2 {
77			t.Fatalf("export result=%+v, want 3 entries 2 objects", res)
78		}
79	
80		dst := filepath.Join(t.TempDir(), "vault")
81		if err := New(dst).Init(); err != nil {
82			t.Fatal(err)
83		}
84		ires, err := New(dst).ImportSnapshot(out)
85		if err != nil {
86			t.Fatal(err)
87		}
88		if ires.Entries != 3 || ires.NewObjects != 2 {
89			t.Fatalf("import result=%+v, want 3 entries 2 new objects", ires)
90		}
91		// A fresh store (simulating restart) lists and restores the snapshot.
