178	func TestIncrementalExportImport(t *testing.T) {
179		src, srcStore := seedVault(t, map[string]string{
180			"keep.txt":   "same",
181			"change.txt": "old",
182			"gone.txt":   "leaving",
183		})
184		if _, err := New(src).CreateSnapshot("base"); err != nil {
185			t.Fatal(err)
186		}
187		// Evolve the mapping: overwrite change.txt, add new.txt, drop gone.txt.
188		if _, err := New(src).Put("change.txt", writeFile(t, "new")); err != nil {
189			t.Fatal(err)
190		}
191		if _, err := New(src).Put("new.txt", writeFile(t, "brand new")); err != nil {
192			t.Fatal(err)
193		}
194		idx, err := srcStore.load()
195		if err != nil {
196			t.Fatal(err)
197		}
198		delete(idx.Entries, "gone.txt")
199		target := Snapshot{Name: "target", Entries: idx.Entries}
200		if err := srcStore.saveSnapshot(srcStore.snapshotPath("target"), target); err != nil {
201			t.Fatal(err)
202		}
203	
204		full := filepath.Join(t.TempDir(), "base.pkg")
205		delta := filepath.Join(t.TempDir(), "target.pkg")
206		if res := mustExport(t, src, "base", "", full); res.Objects != 3 {
207			t.Fatalf("base objects=%d, want 3", res.Objects)
208		}
209		res := mustExport(t, src, "target", "base", delta)
210		// Base digests: same, old, leaving. Target digests: same, new, brand new.
211		// The delta carries the two non-base digests despite three entries.
212		if res.Entries != 3 || res.Objects != 2 {
213			t.Fatalf("delta result=%+v, want 3 entries 2 objects", res)
214		}
215	
216		dst := filepath.Join(t.TempDir(), "vault")
217		if err := New(dst).Init(); err != nil {
218			t.Fatal(err)
219		}
220		// Delta without the base is refused.
221		if _, err := New(dst).ImportSnapshot(delta); err == nil {
222			t.Fatal("delta imported without a base snapshot")
223		}
224		if _, err := New(dst).ImportSnapshot(full); err != nil {
225			t.Fatal(err)
226		}
227		ires, err := New(dst).ImportSnapshot(delta)
228		if err != nil {
229			t.Fatal(err)
230		}
231		if ires.NewObjects != 2 {
232			t.Fatalf("delta new objects=%d, want 2", ires.NewObjects)
233		}
234		// Add, overwrite, and disappearance are all governed by the target mapping.
235		assertEntriesAfterRestore(t, dst, "target", map[string]string{
236			"keep.txt":   "same",
237			"change.txt": "new",
238			"new.txt":    "brand new",
239		})
240		// gone.txt must not be resurrected by restoring the target.
241		entries, err := New(dst).List()
242		if err != nil {
243			t.Fatal(err)
244		}
245		for _, e := range entries {
246			if e.Name == "gone.txt" {
247				t.Fatal("deleted name reappeared after restore")
248			}
249		}
250	}
